chrome.tabs.onActivated.addListener(({tabId:e})=>{chrome.tabs.get(e,t=>{t.url?.startsWith(`https://mail.google.com`)??!1?chrome.action.enable(e).catch(()=>{}):chrome.action.disable(e).catch(()=>{})})}),chrome.tabs.onUpdated.addListener((e,t,n)=>{t.status===`complete`&&(n.url?.startsWith(`https://mail.google.com`)??!1?chrome.action.enable(e).catch(()=>{}):chrome.action.disable(e).catch(()=>{}))});var e=(e,t)=>{chrome.tabs.sendMessage(e,t).catch(t=>{console.error(`[ToneFit BG] content script 전달 실패 (tabId:`,e,`)`,t.message)})};chrome.runtime.onMessage.addListener((t,n,r)=>{if(t.type===`PING`)return r({type:`PONG`}),!0;if(t.type===`OPEN_SIDE_PANEL`){let e=n.tab?.id;return e!=null&&chrome.sidePanel.open({tabId:e}).catch(console.error),!0}if(t.type===`INSERT_EMAIL`||t.type===`GENERATION_START`||t.type===`GENERATION_ERROR`){let n=t.tabId;return n==null?console.error(`[ToneFit BG] tabId 없음 — 메시지 전송 불가`):e(n,t),!0}return!0});